    const good = a === 1 ? 'e - 1' : a === -1 ? '1 - e^{-1}' : a > 0 ? `\\frac{e^{${a}} - 1}{${a}}` : `\\frac{1 - e^{${a}}}{${-a}}`;
    const dists = [L(ea), L('1'), L(`${ea} + 1`), L(a === 1 ? '\\frac{e}{2}' : a > 0 ? `\\frac{${ea} + 1}{${a}}` : a === -1 ? 'e - 1' : `\\frac{e^{${-a}} - 1}{${-a}}`), L(a === 1 ? 'e' : `${ea} - 1`)];
