        const A = (x, y, rr) => `Centre $\\Omega${pt(x, y)}$, rayon $${rr}$`;
        const sqx = h === 0 ? 'x^2' : `(${this.poly([[1, 'x'], [-h, '']])})^2 - ${h * h}`;
